// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        // Only test when msg.value is non-zero so that transfer matters
        vm.assume(value > 0);
        uint256 balanceBefore = address(c).balance;
        // Fund the contract so it has balance even without msg.value (if needed)
        vm.deal(address(c), balanceBefore + value);
        // Make the external call revert by providing a target that will revert
        // We'll deploy a contract that reverts on any call
        // For simplicity, we use a previous trick: set the target to self (reverts on call)
        // But the target is fixed in the contract, so we can't change it.
        // Instead, we note that the external call may succeed or revert depending on context.
        // To observe the property, we need a scenario where the external call reverts.
        // Since we control the target address externally? No, we don't.
        // So this property cannot be tested directly without controlling the target.
        // We need a different approach: the difference is that after a successful call, M does not transfer balance.
        // So the rule is: after go(), the contract balance is 0 if the external call succeeded.
        // But we cannot control the external call success from fuzz.
        // The only way is to use vm.assume that the call succeeds, but we cannot know.
        // Therefore, this property is not fuzzable with fixed target.
        // Hence we must choose a different general rule that is testable.
        // The known difference: after go() with any msg.value, the contract balance is 0 in P, non-zero in M.
        // But that was already tried and failed because the external call may revert and leave balance.
        // So we need to precondition that the external call succeeds.
        // Since the target is a fixed address, we can deposit ether to that address beforehand so it can accept it via fallback.
        // We'll give the target address some ether to ensure it accepts calls.
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        vm.deal(target, 1 ether); // ensure target has fallback that doesn't revert
        // Now call go with value
        c.go{value: value}();
        // After a successful call, the contract balance must be 0 in P but not in M.
        // But we cannot know if the call succeeded unless we check? Actually if it failed, it would revert.
        // So if the call doesn't revert, we know it succeeded.
        // So the test passes as long as the call doesn't revert, which we assumed via vm.deal.
        assertTrue(address(c).balance == 0, "Balance should be zero after go()");
    }
}

