pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, address(this).balance);
        address owner = c.owner();
        uint256 balanceBefore = owner.balance;
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.go.selector));
        assertTrue(success, "call should succeed");
