pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e24);

        // Ensure owner has enough ETH to receive transfer (though not needed for this test)
        vm.deal(address(c), 0);

        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));

        // If external call succeeded (which it should for non-reverting case), contract balance must be zero
        if (success) {
            assertTrue(address(c).balance == 0, "Contract balance should be zero after go()");
        }
    }
}
